/**
 * Level metadata for all 10 vocabulary levels.
 */
export const VOCAB_LEVELS: readonly VocabLevel[] = Array.from({ length: VOCAB_LEVEL_COUNT }, (_, i) => ({
  level: i + 1,
  wordCount: VOCAB_WORDS.filter((w) => w.level === i + 1).length,
}));

// ---------------------------------------------------------------------------
// Helper functions
// ---------------------------------------------------------------------------

/**
 * Returns all words for a given level.
 * @param level - The level number (1–10).
 * @returns Array of VocabWord objects for that level.
 */
export function getWordsByLevel(level: number): VocabWord[] {
  return VOCAB_WORDS.filter((w) => w.level === level);
}

/**
 * Picks n random items from an array (Fisher-Yates shuffle, then slice).
 * @param arr - The source array.
 * @param n - Number of items to pick.
 * @returns A new array with n randomly selected items.
 */
export function pickRandom<T>(arr: readonly T[], n: number): T[] {
  const shuffled = [...arr];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled.slice(0, n);
}
